function smart_sort_array($set, $order = 'asc') {
    // Check if the input is valid
    if (!is_array($set) || !all_keys_exist_in_set($set)) {
        return false;
    }

    // Sort the array
    usort($set, function ($a, $b) use ($order) {
        $value_a = isset($a['age']) ? $a['age'] : null;
        $value_b = isset($b['age']) ? $b['age'] : null;

        switch ($order) {
            case 'asc':
