	if err != nil {
		fmt.Printf("Error reading file %s: %v\n", sourceFile, err)
		return
	}

	parsed, err := parser.ParseFile(token.NewFileSet(), "", string(file), 0)
	if err != nil {
		fmt.Printf("Error parsing file %s: %v\n", sourceFile, err)
		return
	}

	ast.Inspect(parsed, func(n ast.Node) bool {
		if n == nil || !isStructDeclaration(n) {
			return false
		}
		structType, ok := n.(*ast.StructType)
		if !ok {
			return true
		}

		schema := makeSchema(structType.Fields...)
		err = WriteAvroSchema(structName, schema)
		if err != nil {
			fmt.Printf("Error writing Avro schema for struct %s: %v\n", structName, err)
