// isStructDeclaration checks if a node represents a struct declaration.
func isStructDeclaration(node ast.Node) bool {
	switch n := node.(type) {
	case *ast.GenDecl:
		if n.Tok == token.TYPE && len(n.SpecList.List) > 0 {
			for _, spec := range n.SpecList.List {
				if spec.N.Signature.Name.Kind() == reflect.Struct {
					return true
				}
			}
		}
	default:
		return false
	}
	return false
}

